o.deleted = FALSE
AND o.status = 'CONFIRMED'
AND o.confirmed_at >= #{startAt}
AND o.confirmed_at < #{endAt}

o.deleted = FALSE
AND o.status IN ('SUBMITTED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'SHORT_CLOSED')
AND o.status = #{query.status}
AND o.submitted_at >= #{startAt}
AND o.submitted_at < #{endAt}

FROM inventory_movement m
JOIN purchase_receipt_item ri ON ri.id = m.source_document_item_id AND ri.deleted = FALSE
JOIN purchase_receipt r ON r.id = ri.purchase_receipt_id AND r.deleted = FALSE
JOIN purchase_order_item poi ON poi.id = ri.purchase_order_item_id AND poi.deleted = FALSE
JOIN purchase_order po ON po.id = poi.purchase_order_id AND po.deleted = FALSE
WHERE m.deleted = FALSE
AND m.source_document_type = 'PURCHASE_RECEIPT_ITEM'
AND m.movement_type = 'PURCHASE_IN'
AND m.occurred_at >= #{startAt}
AND m.occurred_at < #{endAt}
AND r.supplier_id = #{query.supplierId}
AND po.purchaser_id = #{query.purchaserId}
AND r.warehouse_id = #{query.warehouseId}


    AND m.warehouse_id IN
    #{scopeId}


    AND FALSE

mapper.select:
SELECT ord.confirmedOrderCount,
       ord.customerCount,
       ord.confirmedOrderAmount,
       rf.completedRefundAmount,
       po.submittedOrderCount,
       po.submittedAmount                       AS submittedPurchaseAmount,
       mv.purchaseInCostAmount,
       mv.purchaseInCostMissingCount,
       bal.inventoryBookValue,
       bal.stockedSkuCount,
       CURRENT_TIMESTAMP                        AS snapshotAt
FROM (SELECT COUNT(*)                            AS confirmedOrderCount,
             COUNT(DISTINCT o.customer_id)      AS customerCount,
             COALESCE(SUM(o.settlement_total_amount), 0) AS confirmedOrderAmount
      FROM sales_order o
      WHERE o.deleted = FALSE
        AND o.status = 'CONFIRMED'
        AND o.confirmed_at >= #{startAt}
        AND o.confirmed_at < #{endAt}
        AND o.customer_id = #{query.customerId}
        AND o.seller_id = #{query.sellerId}

            AND o.order_source = #{query.orderSource}
        ) ord
         CROSS JOIN (SELECT COALESCE(SUM(r.refund_amount), 0) AS completedRefundAmount
                     FROM order_refund r
                     WHERE r.deleted = FALSE
                       AND r.status = 'COMPLETED'
                       AND r.completed_at >= #{startAt}
                       AND r.completed_at < #{endAt}) rf
         CROSS JOIN (SELECT COUNT(*)                        AS submittedOrderCount,
                              COALESCE(SUM(o2.total_amount), 0) AS submittedAmount
                       FROM purchase_order o2
                       WHERE o2.deleted = FALSE
                         AND o2.status IN ('SUBMITTED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'SHORT_CLOSED')
                         AND o2.submitted_at >= #{startAt}
                         AND o2.submitted_at < #{endAt}
                       AND o2.warehouse_id = #{query.warehouseId}

                           AND o2.warehouse_id IN
                           #{scopeId}


                           AND FALSE
                       ) po
         CROSS JOIN (SELECT COALESCE(SUM(m.quantity * m.unit_cost), 0)               AS purchaseInCostAmount,
                              COUNT(*) FILTER (WHERE m.unit_cost IS NULL)             AS purchaseInCostMissingCount
                       FROM inventory_movement m
                       WHERE m.deleted = FALSE
                         AND m.movement_type = 'PURCHASE_IN'
                         AND m.occurred_at >= #{startAt}
                         AND m.occurred_at < #{endAt}
                       AND m.warehouse_id = #{query.warehouseId}

                           AND m.warehouse_id IN
                           #{scopeId}


                           AND FALSE
                       ) mv
         CROSS JOIN (SELECT COALESCE(SUM(b.quantity * b.avg_cost), 0)               AS inventoryBookValue,
                              COUNT(*) FILTER (WHERE b.quantity > 0)              AS stockedSkuCount
                       FROM inventory_balance b
                       WHERE b.deleted = FALSE
                       AND b.warehouse_id = #{query.warehouseId}

                           AND b.warehouse_id IN
                           #{scopeId}


                           AND FALSE
                       ) bal

SELECT TO_CHAR(d.day, 'YYYY-MM-DD') AS bizDate, COALESCE(so.order_count, 0) AS confirmedOrderCount, COALESCE(so.customer_count, 0) AS customerCount, COALESCE(so.order_amount, 0) AS confirmedOrderAmount, COALESCE(rf.refund_amount, 0) AS completedRefundAmount, COALESCE(po.purchase_amount, 0) AS submittedPurchaseAmount, COALESCE(mv.cost_amount, 0) AS purchaseInCostAmount, COALESCE(mv.cost_missing_count, 0) AS purchaseInCostMissingCount FROM generate_series(#{startDate}::date, #{endDate}::date, INTERVAL '1 day') AS d(day) LEFT JOIN (SELECT (o.confirmed_at AT TIME ZONE 'Asia/Shanghai')::date AS day, COUNT(*) AS order_count, COUNT(DISTINCT o.customer_id) AS customer_count, SUM(o.settlement_total_amount) AS order_amount FROM sales_order o WHERE o.deleted = FALSE AND o.status = 'CONFIRMED' AND o.confirmed_at >= #{startAt} AND o.confirmed_at < #{endAt} AND o.customer_id = #{query.customerId} AND o.seller_id = #{query.sellerId}
AND o.order_source = #{query.orderSource}
GROUP BY 1) so ON so.day = CAST(d.day AS date) LEFT JOIN (SELECT (r.completed_at AT TIME ZONE 'Asia/Shanghai')::date AS day, SUM(r.refund_amount) AS refund_amount FROM order_refund r WHERE r.deleted = FALSE AND r.status = 'COMPLETED' AND r.completed_at >= #{startAt} AND r.completed_at < #{endAt} GROUP BY 1) rf ON rf.day = CAST(d.day AS date) LEFT JOIN (SELECT (o2.submitted_at AT TIME ZONE 'Asia/Shanghai')::date AS day, SUM(o2.total_amount) AS purchase_amount FROM purchase_order o2 WHERE o2.deleted = FALSE AND o2.status IN ('SUBMITTED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'SHORT_CLOSED') AND o2.submitted_at >= #{startAt} AND o2.submitted_at < #{endAt} AND o2.warehouse_id = #{query.warehouseId}
AND o2.warehouse_id IN #{scopeId}
AND FALSE
GROUP BY 1) po ON po.day = CAST(d.day AS date) LEFT JOIN (SELECT (m.occurred_at AT TIME ZONE 'Asia/Shanghai')::date AS day, SUM(m.quantity * m.unit_cost) AS cost_amount, COUNT(*) FILTER (WHERE m.unit_cost IS NULL) AS cost_missing_count FROM inventory_movement m WHERE m.deleted = FALSE AND m.movement_type = 'PURCHASE_IN' AND m.occurred_at >= #{startAt} AND m.occurred_at < #{endAt} AND m.warehouse_id = #{query.warehouseId}
AND m.warehouse_id IN #{scopeId}
AND FALSE
GROUP BY 1) mv ON mv.day = CAST(d.day AS date) ORDER BY d.day

SELECT i.sku_id AS id, MAX(i.product_name_snapshot) AS name, SUM(i.settlement_line_amount) AS amount FROM sales_order_item i JOIN sales_order o ON o.id = i.order_id
WHERE i.deleted = FALSE AND
GROUP BY i.sku_id ORDER BY SUM(i.settlement_line_amount) DESC NULLS LAST, i.sku_id LIMIT #{limit}

SELECT cat.id AS id, MAX(cat.name) AS name, SUM(i.settlement_line_amount) AS amount FROM sales_order_item i JOIN sales_order o ON o.id = i.order_id
WHERE i.deleted = FALSE AND cat.id IS NOT NULL AND
GROUP BY cat.id ORDER BY SUM(i.settlement_line_amount) DESC NULLS LAST, cat.id LIMIT #{limit}

SELECT o.customer_id AS id, MAX(o.customer_name_snapshot) AS name, SUM(i.settlement_line_amount) AS amount FROM sales_order o JOIN sales_order_item i ON i.order_id = o.id AND i.deleted = FALSE
WHERE
GROUP BY o.customer_id ORDER BY SUM(i.settlement_line_amount) DESC NULLS LAST, o.customer_id LIMIT #{limit}

SELECT po.submittedOrderCount,
       po.submittedAmount,
       rc.confirmedReceiptCount,
       rc.receiptReferenceAmount,
       mv.purchaseInCostAmount,
       mv.purchaseInCostMissingCount,
       pd.pendingPutawayReceiptCount
FROM (SELECT COUNT(*)                            AS submittedOrderCount,
             COALESCE(SUM(o.total_amount), 0)   AS submittedAmount
      FROM purchase_order o
      WHERE o.deleted = FALSE
        AND o.status IN ('SUBMITTED', 'PARTIALLY_RECEIVED', 'RECEIVED', 'SHORT_CLOSED')
        AND o.submitted_at >= #{startAt}
        AND o.submitted_at < #{endAt}
        AND o.supplier_id = #{query.supplierId}
        AND o.purchaser_id = #{query.purchaserId}
        AND o.warehouse_id = #{query.warehouseId}

            AND o.warehouse_id IN
            #{scopeId}


            AND FALSE
        ) po
         CROSS JOIN (SELECT COUNT(DISTINCT r.id)                                    AS confirmedReceiptCount,
                              COALESCE(SUM(ri.received_quantity * oi.purchase_price), 0) AS receiptReferenceAmount
                     FROM purchase_receipt r
                              JOIN purchase_receipt_item ri
                                   ON ri.purchase_receipt_id = r.id AND ri.deleted = FALSE
                              JOIN purchase_order_item oi
                                   ON oi.id = ri.purchase_order_item_id AND oi.deleted = FALSE
                              JOIN purchase_order o2
                                   ON o2.id = oi.purchase_order_id AND o2.deleted = FALSE
                     WHERE r.deleted = FALSE
                       AND r.status = 'CONFIRMED'
                       AND r.confirmed_at >= #{startAt}
                       AND r.confirmed_at < #{endAt}
                       AND r.supplier_id = #{query.supplierId}
                       AND r.warehouse_id = #{query.warehouseId}
                       AND o2.purchaser_id = #{query.purchaserId}

                           AND r.warehouse_id IN
                           #{scopeId}


                           AND FALSE
                       ) rc
         CROSS JOIN (SELECT COALESCE(SUM(m.quantity * m.unit_cost), 0)          AS purchaseInCostAmount,
                              COUNT(*) FILTER (WHERE m.unit_cost IS NULL)        AS purchaseInCostMissingCount
                     FROM inventory_movement m
                              JOIN purchase_receipt_item ri
                                   ON ri.id = m.source_document_item_id AND ri.deleted = FALSE
                              JOIN purchase_receipt r
                                   ON r.id = ri.purchase_receipt_id AND r.deleted = FALSE
                              JOIN purchase_order_item oi
                                   ON oi.id = ri.purchase_order_item_id AND oi.deleted = FALSE
                              JOIN purchase_order o2
                                   ON o2.id = oi.purchase_order_id AND o2.deleted = FALSE
                     WHERE m.deleted = FALSE
                       AND m.source_document_type = 'PURCHASE_RECEIPT_ITEM'
                       AND m.movement_type = 'PURCHASE_IN'
                       AND m.occurred_at >= #{startAt}
                       AND m.occurred_at < #{endAt}
                       AND r.supplier_id = #{query.supplierId}
                       AND r.warehouse_id = #{query.warehouseId}
                       AND o2.purchaser_id = #{query.purchaserId}


                           AND m.warehouse_id IN
                           #{scopeId}


                           AND FALSE
                       ) mv

         CROSS JOIN (SELECT COUNT(*) AS pendingPutawayReceiptCount
                     FROM purchase_receipt r2
                     WHERE r2.deleted = FALSE
                       AND r2.status = 'CONFIRMED'
                       AND r2.receipt_mode = 'WAREHOUSE_CONFIRM'
                       AND r2.putaway_status = 'PENDING'

                           AND r2.warehouse_id IN
                           #{scopeId}


                           AND FALSE
                       ) pd

WITH po AS (SELECT o.supplier_id, COUNT(DISTINCT o.id) AS order_count, COUNT(DISTINCT oi.sku_id) AS sku_kind_count, SUM(oi.line_amount) AS order_amount, MAX(o.submitted_at) AS last_submitted_at FROM purchase_order o JOIN purchase_order_item oi ON oi.purchase_order_id = o.id AND oi.deleted = FALSE WHERE
GROUP BY o.supplier_id), rc AS (SELECT r.supplier_id, COALESCE(SUM(ri.received_quantity * oi.purchase_price), 0) AS receipt_reference_amount FROM purchase_receipt r JOIN purchase_receipt_item ri ON ri.purchase_receipt_id = r.id AND ri.deleted = FALSE JOIN purchase_order_item oi ON oi.id = ri.purchase_order_item_id AND oi.deleted = FALSE JOIN purchase_order o2 ON o2.id = oi.purchase_order_id AND o2.deleted = FALSE WHERE r.deleted = FALSE AND r.status = 'CONFIRMED' AND r.confirmed_at >= #{startAt} AND r.confirmed_at < #{endAt} AND r.supplier_id = #{query.supplierId} AND r.warehouse_id = #{query.warehouseId} AND o2.purchaser_id = #{query.purchaserId}
AND r.warehouse_id IN #{scopeId}
AND FALSE
GROUP BY r.supplier_id), ic AS (SELECT q.supplier_id, SUM(q.cost_amount) AS inbound_cost_amount, SUM(q.cost_missing_count) AS inbound_cost_missing_count FROM (SELECT m.source_document_id, r2.supplier_id, COALESCE(SUM(m.quantity * m.unit_cost), 0) AS cost_amount, COUNT(*) FILTER (WHERE m.unit_cost IS NULL) AS cost_missing_count FROM inventory_movement m JOIN purchase_receipt_item ri ON ri.id = m.source_document_item_id AND ri.deleted = FALSE JOIN purchase_receipt r2 ON r2.id = ri.purchase_receipt_id AND r2.deleted = FALSE JOIN purchase_order_item poi ON poi.id = ri.purchase_order_item_id AND poi.deleted = FALSE JOIN purchase_order po2 ON po2.id = poi.purchase_order_id AND po2.deleted = FALSE WHERE m.deleted = FALSE AND m.source_document_type = 'PURCHASE_RECEIPT_ITEM' AND m.movement_type = 'PURCHASE_IN' AND m.occurred_at >= #{startAt} AND m.occurred_at < #{endAt} AND r2.warehouse_id = #{query.warehouseId} AND po2.purchaser_id = #{query.purchaserId}
AND m.warehouse_id IN #{scopeId}
AND FALSE
GROUP BY m.source_document_id, r2.supplier_id) q GROUP BY q.supplier_id) SELECT po.supplier_id AS supplierId, sp.supplier_code AS supplierCode, sp.name AS supplierName, po.order_count AS orderCount, po.sku_kind_count AS skuKindCount, po.order_amount AS orderAmount, COALESCE(rc.receipt_reference_amount, 0) AS receiptReferenceAmount, COALESCE(ic.inbound_cost_amount, 0) AS inboundCostAmount, COALESCE(ic.inbound_cost_missing_count, 0) AS inboundCostMissingCount, po.last_submitted_at AS lastSubmittedAt, RANK() OVER (ORDER BY po.order_amount DESC NULLS LAST) AS amountRank FROM po LEFT JOIN supplier sp ON sp.id = po.supplier_id AND sp.deleted = FALSE LEFT JOIN rc ON rc.supplier_id = po.supplier_id LEFT JOIN ic ON ic.supplier_id = po.supplier_id ORDER BY po.order_amount DESC NULLS LAST, po.supplier_id

SELECT r.supplier_id AS id, MAX(r.supplier_name_snapshot) AS name, COALESCE(SUM(m.quantity * m.unit_cost), 0) AS amount FROM inventory_movement m JOIN purchase_receipt_item ri ON ri.id = m.source_document_item_id AND ri.deleted = FALSE JOIN purchase_receipt r ON r.id = ri.purchase_receipt_id AND r.deleted = FALSE WHERE m.deleted = FALSE AND m.source_document_type = 'PURCHASE_RECEIPT_ITEM' AND m.movement_type = 'PURCHASE_IN' AND m.occurred_at >= #{startAt} AND m.occurred_at < #{endAt} AND r.warehouse_id = #{query.warehouseId}
AND m.warehouse_id IN #{scopeId}
AND FALSE
GROUP BY r.supplier_id ORDER BY SUM(m.quantity * m.unit_cost) DESC NULLS LAST, r.supplier_id LIMIT #{limit}

WITH po AS (SELECT o.purchaser_id, COUNT(DISTINCT o.id) AS order_count, COUNT(DISTINCT oi.sku_id) AS sku_kind_count, SUM(oi.line_amount) AS order_amount, MAX(o.submitted_at) AS last_submitted_at FROM purchase_order o JOIN purchase_order_item oi ON oi.purchase_order_id = o.id AND oi.deleted = FALSE WHERE
GROUP BY o.purchaser_id), rc AS (SELECT o2.purchaser_id, COALESCE(SUM(ri.received_quantity * oi.purchase_price), 0) AS receipt_reference_amount FROM purchase_receipt r JOIN purchase_receipt_item ri ON ri.purchase_receipt_id = r.id AND ri.deleted = FALSE JOIN purchase_order_item oi ON oi.id = ri.purchase_order_item_id AND oi.deleted = FALSE JOIN purchase_order o2 ON o2.id = oi.purchase_order_id AND o2.deleted = FALSE WHERE r.deleted = FALSE AND r.status = 'CONFIRMED' AND r.confirmed_at >= #{startAt} AND r.confirmed_at < #{endAt} AND r.supplier_id = #{query.supplierId} AND r.warehouse_id = #{query.warehouseId} AND o2.purchaser_id = #{query.purchaserId}
AND r.warehouse_id IN #{scopeId}
AND FALSE
GROUP BY o2.purchaser_id), ic AS (SELECT q.purchaser_id, SUM(q.cost_amount) AS inbound_cost_amount, SUM(q.cost_missing_count) AS inbound_cost_missing_count FROM (SELECT po2.purchaser_id, COALESCE(SUM(m.quantity * m.unit_cost), 0) AS cost_amount, COUNT(*) FILTER (WHERE m.unit_cost IS NULL) AS cost_missing_count FROM inventory_movement m JOIN purchase_receipt_item ri ON ri.id = m.source_document_item_id AND ri.deleted = FALSE JOIN purchase_receipt r2 ON r2.id = ri.purchase_receipt_id AND r2.deleted = FALSE JOIN purchase_order_item poi ON poi.id = ri.purchase_order_item_id AND poi.deleted = FALSE JOIN purchase_order po2 ON po2.id = poi.purchase_order_id AND po2.deleted = FALSE WHERE m.deleted = FALSE AND m.source_document_type = 'PURCHASE_RECEIPT_ITEM' AND m.movement_type = 'PURCHASE_IN' AND m.occurred_at >= #{startAt} AND m.occurred_at < #{endAt} AND r2.supplier_id = #{query.supplierId} AND r2.warehouse_id = #{query.warehouseId} AND po2.purchaser_id = #{query.purchaserId}
AND m.warehouse_id IN #{scopeId}
AND FALSE
GROUP BY po2.purchaser_id, m.id) q GROUP BY q.purchaser_id) SELECT po.purchaser_id AS purchaserId, COALESCE(MAX(e.actual_name), '未分配采购员') AS purchaserName, MAX(po.order_count) AS orderCount, MAX(po.sku_kind_count) AS skuKindCount, MAX(po.order_amount) AS orderAmount, COALESCE(MAX(rc.receipt_reference_amount), 0) AS receiptReferenceAmount, COALESCE(MAX(ic.inbound_cost_amount), 0) AS inboundCostAmount, COALESCE(MAX(ic.inbound_cost_missing_count), 0) AS inboundCostMissingCount, MAX(po.last_submitted_at) AS lastSubmittedAt FROM po LEFT JOIN t_employee e ON e.employee_id = po.purchaser_id AND e.deleted_flag = FALSE LEFT JOIN rc ON rc.purchaser_id IS NOT DISTINCT FROM po.purchaser_id LEFT JOIN ic ON ic.purchaser_id IS NOT DISTINCT FROM po.purchaser_id GROUP BY po.purchaser_id ORDER BY MAX(po.order_amount) DESC NULLS LAST, po.purchaser_id

SELECT r.id AS receiptId, ri.id AS receiptItemId, r.receipt_no AS receiptNo, r.purchase_order_no_snapshot AS purchaseOrderNo, r.purchase_order_id AS purchaseOrderId, r.supplier_name_snapshot AS supplierName, r.warehouse_name_snapshot AS warehouseName, r.receipt_mode AS receiptMode, r.putaway_status AS putawayStatus, r.confirmed_at AS confirmedAt, ri.spu_code_snapshot AS spuCode, ri.product_name_snapshot AS productName, ri.sku_code_snapshot AS skuCode, ri.sku_name_snapshot AS skuName, ri.purchase_unit_snapshot AS purchaseUnit, ri.received_quantity AS receivedQuantity, ri.cumulative_received_quantity AS cumulativeReceivedQuantity, ri.remaining_quantity AS remainingQuantity, ri.over_receipt_quantity AS overReceiptQuantity, ri.receipt_difference AS receiptDifference, oi.purchase_price AS purchasePrice, ROUND(ri.received_quantity * oi.purchase_price, 4) AS receiptReferenceAmount FROM purchase_receipt r JOIN purchase_receipt_item ri ON ri.purchase_receipt_id = r.id AND ri.deleted = FALSE JOIN purchase_order_item oi ON oi.id = ri.purchase_order_item_id AND oi.deleted = FALSE WHERE r.deleted = FALSE AND r.status = 'CONFIRMED' AND r.confirmed_at >= #{startAt} AND r.confirmed_at < #{endAt} AND r.supplier_id = #{query.supplierId} AND r.warehouse_id = #{query.warehouseId}
AND r.warehouse_id IN #{scopeId}
AND FALSE
AND r.purchase_order_id = #{query.purchaseOrderId}
AND r.receipt_mode = #{query.receiptMode}
AND r.putaway_status = #{query.putawayStatus}
AND (r.receipt_no ILIKE CONCAT('%', #{query.keyword}, '%') OR r.purchase_order_no_snapshot ILIKE CONCAT('%', #{query.keyword}, '%') OR ri.product_name_snapshot ILIKE CONCAT('%', #{query.keyword}, '%') OR ri.sku_code_snapshot ILIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY r.confirmed_at DESC, r.id DESC, ri.sort_order, ri.id

SELECT m.id AS movementId, m.occurred_at AS occurredAt, w.name AS warehouseName, r.receipt_no AS receiptNo, r.purchase_order_no_snapshot AS purchaseOrderNo, r.supplier_name_snapshot AS supplierName, spu.name AS productName, k.sku_code AS skuCode, m.unit_snapshot AS unit, m.quantity AS quantity, m.unit_cost AS unitCost, ROUND(m.quantity * m.unit_cost, 4) AS costAmount, (m.unit_cost IS NULL) AS costMissing, m.operator AS operator FROM inventory_movement m JOIN purchase_receipt_item ri ON ri.id = m.source_document_item_id AND ri.deleted = FALSE JOIN purchase_receipt r ON r.id = ri.purchase_receipt_id AND r.deleted = FALSE LEFT JOIN warehouse w ON w.id = m.warehouse_id AND w.deleted = FALSE LEFT JOIN product_sku k ON k.id = m.sku_id LEFT JOIN product_spu spu ON spu.id = k.spu_id WHERE m.deleted = FALSE AND m.source_document_type = 'PURCHASE_RECEIPT_ITEM' AND m.movement_type = 'PURCHASE_IN' AND m.occurred_at >= #{startAt} AND m.occurred_at < #{endAt} AND r.supplier_id = #{query.supplierId} AND m.warehouse_id = #{query.warehouseId}
AND m.warehouse_id IN #{scopeId}
AND FALSE
AND r.purchase_order_id = #{query.purchaseOrderId}
AND (r.receipt_no ILIKE CONCAT('%', #{query.keyword}, '%') OR r.purchase_order_no_snapshot ILIKE CONCAT('%', #{query.keyword}, '%') OR spu.name ILIKE CONCAT('%', #{query.keyword}, '%') OR k.sku_code ILIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY m.occurred_at DESC, m.id DESC

SELECT r.id AS receiptId, r.receipt_no AS receiptNo, r.purchase_order_no_snapshot AS purchaseOrderNo, r.purchase_order_id AS purchaseOrderId, r.supplier_name_snapshot AS supplierName, r.warehouse_name_snapshot AS warehouseName, r.confirmed_at AS confirmedAt, COALESCE(MAX(it.sku_kind_count), 0) AS skuKindCount, STRING_AGG(it.unit_snapshot || ' ' || CAST(it.qty AS TEXT), ' / ' ORDER BY it.unit_snapshot) AS quantityText FROM purchase_receipt r LEFT JOIN (SELECT ri.purchase_receipt_id, ri.purchase_unit_snapshot AS unit_snapshot, COUNT(DISTINCT ri.sku_id) AS sku_kind_count, SUM(ri.received_quantity) AS qty FROM purchase_receipt_item ri WHERE ri.deleted = FALSE GROUP BY ri.purchase_receipt_id, ri.purchase_unit_snapshot) it ON it.purchase_receipt_id = r.id WHERE r.deleted = FALSE AND r.status = 'CONFIRMED' AND r.receipt_mode = 'WAREHOUSE_CONFIRM' AND r.putaway_status = 'PENDING' AND r.supplier_id = #{query.supplierId} AND r.warehouse_id = #{query.warehouseId}
AND r.warehouse_id IN #{scopeId}
AND FALSE
AND (r.receipt_no ILIKE CONCAT('%', #{query.keyword}, '%') OR r.purchase_order_no_snapshot ILIKE CONCAT('%', #{query.keyword}, '%'))
GROUP BY r.id ORDER BY r.confirmed_at DESC, r.id DESC

SELECT m.id AS movementId, m.occurred_at AS occurredAt, m.warehouse_id AS warehouseId, w.name AS warehouseName, m.sku_id AS skuId, spu.name AS productName, k.sku_code AS skuCode, m.movement_type AS movementType, m.source_document_type AS sourceDocumentType, AS sourceDocumentNo, m.source_document_id AS sourceDocumentId, m.source_document_item_id AS sourceDocumentItemId, m.quantity AS quantity, m.unit_snapshot AS unit, m.unit_cost AS unitCost, ROUND(m.quantity * m.unit_cost, 4) AS costAmount, m.before_quantity AS beforeQuantity, m.after_quantity AS afterQuantity, m.operator AS operator FROM inventory_movement m LEFT JOIN warehouse w ON w.id = m.warehouse_id AND w.deleted = FALSE LEFT JOIN product_sku k ON k.id = m.sku_id LEFT JOIN product_spu spu ON spu.id = k.spu_id
WHERE m.deleted = FALSE AND m.occurred_at >= #{startAt} AND m.occurred_at < #{endAt} AND m.warehouse_id = #{query.warehouseId}
AND m.warehouse_id IN #{scopeId}
AND FALSE
AND m.sku_id = #{query.skuId}
AND m.movement_type = #{query.movementType}
AND m.source_document_type = #{query.sourceDocumentType}
AND (spu.name ILIKE CONCAT('%', #{query.keyword}, '%') OR k.sku_code ILIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY m.occurred_at DESC, m.id DESC

mapper.sql:
m.deleted = FALSE
AND m.movement_type IN ('STOCKTAKE_LOSS', 'LOSS_REPORT')
AND m.occurred_at >= #{startAt}
AND m.occurred_at < #{endAt}
AND m.warehouse_id = #{query.warehouseId}


    AND m.warehouse_id IN
    #{scopeId}


    AND FALSE

AND m.sku_id = #{query.skuId}

    AND (spu.name ILIKE CONCAT('%', #{query.keyword}, '%')
     OR k.sku_code ILIKE CONCAT('%', #{query.keyword}, '%'))

mapper.select:
SELECT b.id AS balanceId, b.warehouse_id AS warehouseId, w.name AS warehouseName, b.sku_id AS skuId, spu.name AS productName, k.sku_code AS skuCode, b.unit AS unit, b.quantity AS quantity, b.reserved_quantity AS reservedQuantity, b.quantity - b.reserved_quantity AS availableQuantity, b.avg_cost AS avgCost, ROUND(b.quantity * b.avg_cost, 4) AS bookAmount FROM inventory_balance b LEFT JOIN warehouse w ON w.id = b.warehouse_id AND w.deleted = FALSE LEFT JOIN product_sku k ON k.id = b.sku_id LEFT JOIN product_spu spu ON spu.id = k.spu_id WHERE b.deleted = FALSE AND b.warehouse_id = #{query.warehouseId}
AND b.warehouse_id IN #{scopeId}
AND FALSE
AND b.sku_id = #{query.skuId}
AND (spu.name ILIKE CONCAT('%', #{query.keyword}, '%') OR k.sku_code ILIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY ROUND(b.quantity * b.avg_cost, 4) DESC NULLS LAST, b.warehouse_id, b.sku_id

SELECT m.warehouse_id AS warehouseId, MAX(w.name) AS warehouseName, MAX(spu.name) AS productName, MAX(k.sku_code) AS skuCode, m.unit_snapshot AS unit, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'PURCHASE_IN'), 0) AS purchaseInQuantity, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'SALES_OUT'), 0) AS salesOutQuantity, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'STOCKTAKE_GAIN'), 0) AS stocktakeGainQuantity, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'STOCKTAKE_LOSS'), 0) AS stocktakeLossQuantity, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'GAIN_REPORT'), 0) AS gainReportQuantity, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'LOSS_REPORT'), 0) AS lossReportQuantity, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'TRANSFER_IN'), 0) AS transferInQuantity, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'TRANSFER_OUT'), 0) AS transferOutQuantity, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'CONVERT_IN'), 0) AS convertInQuantity, COALESCE(SUM(m.quantity) FILTER (WHERE m.movement_type = 'CONVERT_OUT'), 0) AS convertOutQuantity, COALESCE(SUM(CASE WHEN m.movement_type IN #{t} THEN m.quantity ELSE -m.quantity END), 0) AS netChangeQuantity FROM inventory_movement m LEFT JOIN warehouse w ON w.id = m.warehouse_id AND w.deleted = FALSE LEFT JOIN product_sku k ON k.id = m.sku_id LEFT JOIN product_spu spu ON spu.id = k.spu_id WHERE m.deleted = FALSE AND m.occurred_at >= #{startAt} AND m.occurred_at < #{endAt} AND m.warehouse_id = #{query.warehouseId}
AND m.warehouse_id IN #{scopeId}
AND FALSE
AND m.sku_id = #{query.skuId}
AND (spu.name ILIKE CONCAT('%', #{query.keyword}, '%') OR k.sku_code ILIKE CONCAT('%', #{query.keyword}, '%'))
GROUP BY m.warehouse_id, m.sku_id, m.unit_snapshot ORDER BY m.warehouse_id, m.sku_id
